@Component({
  selector: 'td-icon',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.OnPush,
  template: `<span [innerHTML]="svgMarkup()"></span>`,
  styles: [`
    :host {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      line-height: 0;
    }
    :host > span {
      display: inline-flex;
    }
    :host ::ng-deep svg {
      display: block;
    }
  `],
})
export class TdIconComponent {
  private readonly sanitizer = inject(DomSanitizer);

  readonly name = input.required<TdIconName>();
  readonly size = input<number>(20);
  readonly ariaLabel = input<string | null>(null);

  protected readonly svgMarkup = computed<SafeHtml>(() => {
    const sz = this.size();
    const aria = this.ariaLabel()
      ? ` role="img" aria-label="${this.ariaLabel()}"`
      : ' role="presentation"';
    const svg = `<svg width="${sz}" height="${sz}" viewBox="0 0 24 24" fill="currentColor"${aria}>${ICONS[this.name()]}</svg>`;
    return this.sanitizer.bypassSecurityTrustHtml(svg);
  });
}
